#!/usr/bin/env node
/**
 * Regenerates the screenshots the README embeds.
 *
 * A screenshot in a README is a documented claim like any other, and the least
 * checkable kind: it rots silently, and nobody notices because looking at it
 * is not the same as reading it. So it is generated by a command rather than
 * pasted in, with the appearance pinned so two runs produce the same image for
 * the same app.
 *
 * It captures what the app does, not what it would do with data it cannot get.
 * The price panels are empty in the default shots because they are empty, and
 * the one shot that shows them filled is taken against the demo provider and
 * named so that nobody mistakes it for real figures.
 *
 * Usage, with the app already running:
 *   npm run screenshots                       the default shots
 *   npm run screenshots -- --demo             the generated-price shot
 *   npm run screenshots -- --base http://host:port
 *
 * The app has to be serving; this starts nothing. For the demo shot:
 *   PRICE_PROVIDER=demo npm start
 */
import { chromium } from '@playwright/test';
import { mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = resolve(ROOT, 'docs/screenshots');

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i === -1 ? fallback : process.argv[i + 1];
};
const BASE = arg('base', 'http://127.0.0.1:5174');
const DEMO = process.argv.includes('--demo');

/* Viewport, not full page: /countries renders 85 rows and a full-page capture
   of it is a megabyte of mostly identical table. */
const VIEWPORT = { width: 1280, height: 900 };

const DEFAULT_SHOTS = [
  {
    file: 'dashboard.png',
    path: '/',
    wait: (page) => page.getByText(/What a price would give you/).waitFor(),
    about: 'the dashboard as it is today, price panels empty and saying why',
  },
  {
    file: 'countries.png',
    path: '/countries',
    wait: (page) => page.locator('tbody tr').first().waitFor(),
    about: 'the reporting economies table, sortable and searchable',
  },
  {
    file: 'country-detail.png',
    path: '/countries/BRA',
    wait: (page) => page.getByText(/unit correction was applied/i).waitFor(),
    about: 'a country whose filing was corrected, with the arithmetic shown',
  },
];

const DEMO_SHOTS = [
  {
    file: 'dashboard-generated-prices.png',
    path: '/',
    wait: (page) => page.getByText(/Not a real price/).waitFor(),
    about: 'the same dashboard with a provider configured; these prices are generated',
  },
];

const shots = DEMO ? DEMO_SHOTS : DEFAULT_SHOTS;

await mkdir(OUT, { recursive: true });

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 1 });
const page = await context.newPage();

// Pinned, so a run on somebody else's machine does not produce a dark shot
// because their OS prefers dark. The appearance keys are the ones index.html
// and useTheme.jsx agree on; check:docs holds those two together.
await page.goto(BASE);
await page.evaluate(() => {
  localStorage.setItem('gold-tracker:theme', 'light');
  localStorage.setItem('gold-tracker:contrast', 'normal');
  localStorage.setItem('gold-tracker:font', 'default');
});

let failed = 0;
for (const shot of shots) {
  try {
    await page.goto(BASE + shot.path, { waitUntil: 'networkidle' });
    await shot.wait(page);
    // Settle the web font, so text is not captured mid-swap.
    await page.evaluate(() => document.fonts.ready);
    await page.screenshot({ path: resolve(OUT, shot.file) });
    console.log(`  wrote docs/screenshots/${shot.file}  (${shot.about})`);
  } catch (err) {
    failed += 1;
    console.error(`  FAILED ${shot.file}: ${err.message.split('\n')[0]}`);
    console.error(
      DEMO
        ? '    the demo shot needs: PRICE_PROVIDER=demo npm start'
        : '    the default shots need the app running on the default provider',
    );
  }
}

await browser.close();

if (failed) {
  console.error(`\n${failed} of ${shots.length} screenshots could not be taken.`);
  process.exitCode = 1;
} else {
  console.log(`\n${shots.length} screenshot(s) written to docs/screenshots/.`);
}
